// HasBotIDRef applies the HasEdge predicate on the "bot_id_ref" edge.
func HasBotIDRef() predicate.MemoryExtractionJob {
	return predicate.MemoryExtractionJob(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, BotIDRefTable, BotIDRefColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBotIDRefWith applies the HasEdge predicate on the "bot_id_ref" edge with a given conditions (other predicates).
func HasBotIDRefWith(preds ...predicate.BotAccount) predicate.MemoryExtractionJob {
	return predicate.MemoryExtractionJob(func(s *sql.Selector) {
		step := newBotIDRefStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

