// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MemoryExtractionJob) predicate.MemoryExtractionJob {
	return predicate.MemoryExtractionJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MemoryExtractionJob) predicate.MemoryExtractionJob {
	return predicate.MemoryExtractionJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MemoryExtractionJob) predicate.MemoryExtractionJob {
	return predicate.MemoryExtractionJob(sql.NotPredicates(p))
}
